function Get-WsmCoordinationUtc([string]$Value, [string]$Label, [int]$FreshHours=24) {
    $parsed=[DateTimeOffset]::MinValue
    if(-not [DateTimeOffset]::TryParse($Value,[ref]$parsed) -or $parsed.Offset -ne [TimeSpan]::Zero -or $parsed -gt [DateTimeOffset]::UtcNow.AddMinutes(5) -or $parsed -lt [DateTimeOffset]::UtcNow.AddHours(-$FreshHours)){throw ($Label+' is stale or has an invalid UTC clock.')}
    $parsed
}
function Assert-WsmCoordinationPlan($Plan,[string]$PlanHash) {
    Assert-WsmEnvelope $Plan 'MigrationPlan'
    foreach($id in @($Plan.BatchId,$Plan.PairId,$Plan.ApprovalId,$Plan.Source.HostId,$Plan.Target.HostId)){Assert-WsmId $id}
    if($PlanHash -notmatch '^[a-fA-F0-9]{64}$' -or $Plan.Mode -cne 'IsolatedPilot' -or $Plan.Source.Fingerprint -notmatch '^[a-f0-9]{64}$' -or $Plan.Target.Fingerprint -notmatch '^[a-f0-9]{64}$' -or -not $Plan.Items){throw 'Invalid or incomplete approved plan for coordination.'}
    $Plan
}
function Read-WsmCoordinationGroup([string]$Path,[string]$ExpectedHash) {
    $group=Read-WsmTrustedJson $Path $ExpectedHash;Assert-WsmEnvelope $group 'ConsistencyGroupPlan'
    Assert-WsmId $group.BatchId
    if($group.GroupId -notmatch '^[A-Za-z0-9_. -]{1,128}$'){throw 'Invalid consistency group name.'}
    if(-not $group.Owner -or -not $group.Evidence -or $group.Members.Count -lt 2){throw 'Consistency group requires reviewed owner/evidence and at least two members.'}
    $seen=@{}
    foreach($m in $group.Members){Assert-WsmId $m.PairId;Assert-WsmId $m.SourceHostId;Assert-WsmId $m.TargetHostId;Assert-WsmId $m.ApprovalId
        if($seen.ContainsKey($m.PairId) -or $m.PlanHash -notmatch '^[a-fA-F0-9]{64}$' -or $m.SourceFingerprint -notmatch '^[a-f0-9]{64}$' -or $m.TargetFingerprint -notmatch '^[a-f0-9]{64}$'){throw 'Duplicate or invalid consistency group member.'};$seen[$m.PairId]=$m
    }
    $group
}
function New-WsmConsistencyGroupPlan {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$GroupId,[Parameter(Mandatory)][object[]]$Members,[Parameter(Mandatory)][string]$Owner,[Parameter(Mandatory)][string]$Evidence,[Parameter(Mandatory)][string]$Path)
    if($GroupId -notmatch '^[A-Za-z0-9_. -]{1,128}$'){throw 'Consistency group name must use 1 to 128 letters, digits, spaces, dots, underscores or hyphens.'}
    if([string]::IsNullOrWhiteSpace($Owner) -or [string]::IsNullOrWhiteSpace($Evidence) -or $Members.Count -lt 2){throw 'Group owner/evidence and at least two approved member plans are required.'}
    $rows=New-Object 'System.Collections.Generic.List[object]';$seen=@{};$batch=''
    foreach($entry in $Members){if(-not $entry.PlanPath -or $entry.PlanHash -notmatch '^[a-fA-F0-9]{64}$'){throw 'Each member requires PlanPath and independently obtained PlanHash.'}
        $plan=Read-WsmTrustedJson $entry.PlanPath $entry.PlanHash;[void](Assert-WsmCoordinationPlan $plan $entry.PlanHash)
        if($batch -and $batch -cne $plan.BatchId){throw 'Consistency group members must belong to one batch.'};$batch=$plan.BatchId
        if($seen.ContainsKey($plan.PairId)){throw 'Duplicate pair in consistency group.'};$seen[$plan.PairId]=$true
        $tagged=@($plan.Items | Where-Object {$_.Decision -eq 'Include' -and $_.ConsistencyGroup -ceq $GroupId});if(-not $tagged.Count){throw ('Plan has no included item reviewed for consistency group '+$GroupId+': '+$plan.PairId)}
        foreach($item in $tagged){if(-not $item.ConsistencyOwner -or -not $item.ConsistencyEvidence -or $item.ConsistencyOwner -cne $Owner -or $item.ConsistencyEvidence -cne $Evidence){throw ('Group owner/evidence must match the reviewed item metadata for pair '+$plan.PairId)}}
        $dependencies=@();if($plan.PSObject.Properties['CrossHostDependencies']){$dependencies=@($plan.CrossHostDependencies)}
        $rows.Add([pscustomobject][ordered]@{PairId=$plan.PairId;SourceHostId=$plan.Source.HostId;SourceFingerprint=$plan.Source.Fingerprint;TargetHostId=$plan.Target.HostId;TargetFingerprint=$plan.Target.Fingerprint;ApprovalId=$plan.ApprovalId;InventoryRevision=$plan.InventoryRevision;DecisionRevision=$plan.DecisionRevision;Dependencies=$dependencies;PlanPath=[IO.Path]::GetFullPath($entry.PlanPath);PlanHash=$entry.PlanHash.ToLowerInvariant()})
    }
    $group=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='ConsistencyGroupPlan';GroupId=$GroupId;BatchId=$batch;Owner=$Owner;Evidence=$Evidence;CreatedUtc=(Get-WsmUtc);Members=$rows.ToArray();ProductionVerified=$false}
    Write-WsmJson $Path $group
    [pscustomobject]@{Path=[IO.Path]::GetFullPath($Path);SHA256=(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash;Group=$group}
}
