function Assert-WsmConsistencyGroupBarrier {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$GroupPlanPath,[Parameter(Mandatory)][string]$GroupPlanHash,[Parameter(Mandatory)][ValidateSet('FinalStaged','Activated','RolledBack')][string]$Stage,[Parameter(Mandatory)][object[]]$Receipts,[object[]]$AnchorReceipts=@(),[object[]]$ExternalActivatedReceipts=@())
