        if($Stage -eq 'RolledBack'){$summary=$r.RollbackOutcomeSummary;if(-not $summary -or $summary.IncludedItemCount -lt 1 -or $summary.LocallyRolledBackCount -lt 0 -or $summary.PreExistingUnchangedCount -lt 0 -or $summary.ExternalProcedureReportedCompleteCount -lt 0 -or ($summary.LocallyRolledBackCount+$summary.PreExistingUnchangedCount+$summary.ExternalProcedureReportedCompleteCount) -ne $summary.IncludedItemCount -or ($summary.ExternalProcedureReportedCompleteCount -gt 0 -and $summary.ExternalVerificationLimit -notmatch 'operator-reported attestations')){throw 'Rollback group receipt lacks a complete, explicit typed outcome summary.'}}
        [void](Get-WsmCoordinationUtc $r.ProducedUtc 'Group receipt' 24);[void](Get-WsmCoordinationUtc $r.StageResultProducedUtc 'Member evidence' 24);$freezeExpires=[DateTimeOffset]::MinValue;if(-not [DateTimeOffset]::TryParse($r.FreezeExpiresUtc,[ref]$freezeExpires) -or $freezeExpires.Offset -ne [TimeSpan]::Zero -or (($Stage -in @('FinalStaged','Activated')) -and $freezeExpires -le [DateTimeOffset]::UtcNow)){throw 'Source freeze expired before the consistency barrier.'};$seen[$r.PairId]=$r
