        $anchors=@{};foreach($inputAnchor in $AnchorReceipts){if(-not $inputAnchor.Path -or $inputAnchor.SHA256 -notmatch '^[a-fA-F0-9]{64}$'){throw 'Each final-staged anchor requires a path and independent SHA256.'};$a=Read-WsmTrustedJson $inputAnchor.Path $inputAnchor.SHA256;Assert-WsmEnvelope $a 'ConsistencyGroupReceipt';if($a.GroupId -cne $group.GroupId -or $a.GroupPlanHash -ine $GroupPlanHash -or $a.BatchId -cne $group.BatchId -or $a.Stage -cne 'FinalStaged' -or -not $wanted.ContainsKey($a.PairId) -or $anchors.ContainsKey($a.PairId)){throw 'Final-staged anchor is outside this reviewed group or duplicated.'};$anchors[$a.PairId]=$a}
        foreach($id in $wanted.Keys){if(-not $anchors.ContainsKey($id)){throw ('Final-staged generation anchor missing: '+$id)};$anchor=$anchors[$id];$current=$seen[$id];if($anchor.PlanHash -ine $current.PlanHash -or $anchor.ManifestHash -ine $current.ManifestHash -or $anchor.Generation -ne $current.Generation -or $anchor.FreezeHash -ine $current.FreezeHash -or $anchor.FreezeExpiresUtc -cne $current.FreezeExpiresUtc){throw ('Member receipt drifted from its final-staged generation anchor: '+$id)}}
    }
