            foreach($edge in @($m.Dependencies | Where-Object Type -CEQ 'Mandatory')){if($wanted.ContainsKey($edge.PairId)){continue};$provider=@($ExternalActivatedReceipts | Where-Object {$_.Result.PairId -ceq $edge.PairId -and $_.Result.Stage -ceq 'Cutover' -and $_.Result.Status -ceq 'Succeeded'});if($provider.Count -ne 1 -or $provider[0].IndependentHash -notmatch '^[a-fA-F0-9]{64}$' -or $provider[0].Result.Mode -cne 'IsolatedPilot' -or $provider[0].Result.ProductionVerified -ne $false -or $provider[0].Result.ManifestHash -notmatch '^[a-fA-F0-9]{64}$' -or $provider[0].Result.PayloadGeneration -lt 1){throw ('External mandatory provider must remain activated with a fresh trusted receipt: '+$edge.PairId)};[void](Get-WsmCoordinationUtc $provider[0].Result.ProducedUtc 'External provider activation' 24)}
        }
    }
