function Assert-WsmRollbackResultItemOutcomes($Plan,$Result) {
    if(-not $Result.PSObject.Properties['ItemResults']){throw 'RollbackResult must include a typed outcome for every included item.'}
    $expected=@{};foreach($item in @($Plan.Items | Where-Object Decision -EQ Include)){$expected[$item.ItemId]=$item};$seen=@{}
    foreach($row in @($Result.ItemResults)){
        if(-not $expected.ContainsKey($row.ItemId) -or $seen.ContainsKey($row.ItemId)){throw 'RollbackResult item outcomes are duplicate or outside the approved plan.'};$item=$expected[$row.ItemId];$adapter=[string]$item.MigrationSpec.Adapter
        if($row.Adapter -cne $adapter){throw ('RollbackResult item adapter mismatch: '+$row.ItemId)}
        switch -CaseSensitive ($row.Outcome){
            'RolledBack' {if($row.Verification -cne 'LocalRollbackState' -or $row.StateStatus -cne 'RolledBack' -or $row.JournalHash -ine $Result.JournalHash -or $adapter -in @('ManualWorkflow','WindowsFeature')){throw 'Automatic rollback outcome is not valid for this adapter or local state.'}}
            'PreExistingUnchanged' {if($adapter -eq 'ManualWorkflow' -or $row.Verification -cne 'LocalReadback' -or $row.BeforeHash -notmatch '^[a-fA-F0-9]{64}$' -or $row.ActualHash -ine $row.BeforeHash -or $row.NativeReadbackVerified -ne $true -or -not $row.ReadBackUtc){throw 'Pre-existing unchanged outcome lacks matching local readback hashes.'};[void](Get-WsmCoordinationUtc $row.ReadBackUtc ('Pre-existing item readback '+$row.ItemId) 24)}
            'ExternalProcedureReportedComplete' {if($adapter -notin @('ManualWorkflow','WindowsFeature') -or $row.Verification -cne 'ExternalAttestation' -or $row.ExternalEvidenceHash -notmatch '^[a-fA-F0-9]{64}$' -or $row.ExternalEvidenceItemHash -notmatch '^[a-fA-F0-9]{64}$' -or $row.NativeReadbackVerified -ne $false -or $row.Limitation -notmatch 'did not execute or verify' -or -not $row.EvidenceReference -or -not $row.Owner){throw 'External rollback outcome is not a typed, bounded dedicated-procedure attestation.'}}
            default {throw ('Unknown rollback outcome: '+[string]$row.Outcome)}
        }
        $seen[$row.ItemId]=$true
    }
    if($seen.Count -ne $expected.Count){throw 'RollbackResult lacks a typed outcome for one or more included items.'}
    $true
}
function Export-WsmRollbackResult {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$ManifestPath,[Parameter(Mandatory)][string]$ExpectedHash,[Parameter(Mandatory)][string]$StateDirectory,[Parameter(Mandatory)][string]$Owner,[Parameter(Mandatory)][string]$Evidence,[Parameter(Mandatory)][string]$Path,[string]$DedicatedEvidencePath,[string]$DedicatedEvidenceHash)
    if([string]::IsNullOrWhiteSpace($Owner) -or [string]::IsNullOrWhiteSpace($Evidence)){throw 'Rollback result requires an accountable owner and independent evidence reference.'}
    $package=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;Assert-WsmMigrationHost (Get-WsmMachineIdentity) $package.Manifest.Target.Fingerprint;$operationPaths=Get-WsmOperationPaths $StateDirectory $package.Manifest.PairId
