        $included=@($package.Plan.Items | Where-Object Decision -EQ Include);if(-not $included.Count){throw 'Rollback result cannot be exported for an empty selection.'};$itemsById=@{};foreach($item in $included){if($itemsById.ContainsKey($item.ItemId)){throw 'Approved plan repeats an included item identity.'};$itemsById[$item.ItemId]=$item}
        $recordsById=@{};foreach($record in @($state.Items)){if(-not $itemsById.ContainsKey($record.ItemId) -or $recordsById.ContainsKey($record.ItemId)){throw 'Local rollback state contains an unknown or duplicate item record.'};$recordsById[$record.ItemId]=$record}
