        $externalItems=@($included | Where-Object {$_.MigrationSpec.Adapter -eq 'ManualWorkflow' -or ($_.MigrationSpec.Adapter -eq 'WindowsFeature' -and $recordsById[$_.ItemId].CreatedByTool)})
        $external=$null;$externalRows=@{}
        if($externalItems.Count){if(-not $DedicatedEvidencePath -or $DedicatedEvidenceHash -notmatch '^[a-fA-F0-9]{64}$'){throw 'ManualWorkflow and tool-created WindowsFeature items require typed DedicatedRollbackEvidence; owner text alone is not rollback proof.'};$external=Read-WsmTrustedJson $DedicatedEvidencePath $DedicatedEvidenceHash;Assert-WsmEnvelope $external 'DedicatedRollbackEvidence';if($external.BatchId -cne $package.Manifest.BatchId -or $external.PairId -cne $package.Manifest.PairId -or $external.ApprovalId -cne $package.Manifest.ApprovalId -or $external.PlanHash -ine $package.Manifest.PlanHash -or $external.ManifestHash -ine $ExpectedHash -or $external.Generation -ne $package.Manifest.Generation -or $external.TargetHostId -cne $package.Manifest.Target.HostId -or $external.TargetFingerprint -cne $package.Manifest.Target.Fingerprint -or $external.Mode -cne 'IsolatedPilot' -or $external.ProductionVerified -ne $false -or [string]::IsNullOrWhiteSpace([string]$external.Owner) -or [string]::IsNullOrWhiteSpace([string]$external.Evidence)){throw 'Dedicated rollback evidence is not bound to the exact local plan/package/generation/target.'};[void](Get-WsmCoordinationUtc $external.ProducedUtc 'Dedicated rollback evidence' 24)
            foreach($row in @($external.Items)){if($externalRows.ContainsKey($row.ItemId) -or $row.Adapter -notin @('ManualWorkflow','WindowsFeature') -or $row.Status -cne 'ProcedureReportedComplete' -or [string]::IsNullOrWhiteSpace([string]$row.Procedure) -or [string]::IsNullOrWhiteSpace([string]$row.Evidence) -or [string]::IsNullOrWhiteSpace([string]$row.Owner)){throw 'Dedicated rollback evidence contains an incomplete, duplicate, or unsupported item attestation.'};$externalRows[$row.ItemId]=$row}
            if($externalRows.Count -ne $externalItems.Count){throw 'Dedicated rollback evidence must contain exactly one attestation for each required external procedure.'};foreach($item in $externalItems){$row=$externalRows[$item.ItemId];if($row.Adapter -cne $item.MigrationSpec.Adapter){throw ('Dedicated rollback evidence adapter mismatch: '+$item.ItemId)};[void](Get-WsmCoordinationUtc $row.CompletedUtc ('Dedicated rollback item '+$item.ItemId) 24)}
        }elseif($DedicatedEvidencePath -or $DedicatedEvidenceHash){throw 'Dedicated rollback evidence was supplied when no included item requires an external procedure.'}
        if($state.Stage -ne 'RolledBack' -and -not $externalItems.Count){throw 'Local operation has not reached RolledBack; external evidence is required for every non-automatic outcome.'}
        $outcomes=New-Object 'System.Collections.Generic.List[object]'
        foreach($item in $included){$record=$recordsById[$item.ItemId];$adapter=[string]$item.MigrationSpec.Adapter
            if($adapter -eq 'ManualWorkflow' -or ($adapter -eq 'WindowsFeature' -and $record.CreatedByTool)){$evidenceRow=$externalRows[$item.ItemId];$rowJson=ConvertTo-Json -InputObject $evidenceRow -Depth 20 -Compress;$outcomes.Add([pscustomobject][ordered]@{ItemId=$item.ItemId;Adapter=$adapter;Outcome='ExternalProcedureReportedComplete';Verification='ExternalAttestation';ExternalEvidenceHash=$DedicatedEvidenceHash.ToLowerInvariant();ExternalEvidenceItemHash=(Get-WsmHashText $rowJson);NativeReadbackVerified=$false;Limitation='Operator-supplied dedicated-procedure attestation; migration tool did not execute or verify native product rollback.';EvidenceReference=[string]$evidenceRow.Evidence;Owner=[string]$evidenceRow.Owner}) ;continue}
            if($record.CreatedByTool){if($record.Status -cne 'RolledBack'){throw ('Tool-created item lacks completed automatic rollback: '+$item.ItemId)};$outcomes.Add([pscustomobject][ordered]@{ItemId=$item.ItemId;Adapter=$adapter;Outcome='RolledBack';Verification='LocalRollbackState';StateStatus=[string]$record.Status;NativeReadbackVerified=$false;JournalHash=$state.JournalHash});continue}
            if($record.Status -notin @('Succeeded','RebootRequired')){throw ('Pre-existing item does not have a successful original readback record: '+$item.ItemId)}
            if($adapter -eq 'FileScope'){$actualHash=Get-WsmFileScopeDigest $item.MigrationSpec.TargetPath $item.MigrationSpec.Metadata}else{$check=Test-WsmAdapterConfiguration $item.MigrationSpec;if(-not $check.Passed){throw ('Pre-existing item no longer passes local readback: '+$item.ItemId)};$actualHash=Get-WsmHashText ($check.Actual | ConvertTo-Json -Depth 15 -Compress)}
            if($actualHash -notmatch '^[a-fA-F0-9]{64}$' -or $actualHash -ine $record.ActualHash){throw ('Pre-existing item readback differs from its recorded original configuration: '+$item.ItemId)}
            $outcomes.Add([pscustomobject][ordered]@{ItemId=$item.ItemId;Adapter=$adapter;Outcome='PreExistingUnchanged';Verification='LocalReadback';BeforeHash=$record.ActualHash;ActualHash=$actualHash;ReadBackUtc=(Get-WsmUtc);NativeReadbackVerified=$true})
        }
        if($state.JournalHash -notmatch '^[a-f0-9]{64}$'){throw 'Local operation journal hash is unavailable; rollback result cannot be exported.'}
        $result=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='RollbackResult';BatchId=$package.Manifest.BatchId;PairId=$package.Manifest.PairId;SourceHostId=$package.Manifest.Source.HostId;SourceFingerprint=$package.Manifest.Source.Fingerprint;TargetHostId=$package.Manifest.Target.HostId;TargetFingerprint=$package.Manifest.Target.Fingerprint;ApprovalId=$package.Manifest.ApprovalId;PlanHash=$package.Manifest.PlanHash;ManifestHash=$ExpectedHash.ToLowerInvariant();Generation=$package.Manifest.Generation;Status='RollbackEvidenceComplete';CompletionScope='AutoRollbackAndExplicitReadbackOrExternalAttestation';ItemResults=$outcomes.ToArray();DedicatedEvidencePath=$(if($external){[IO.Path]::GetFullPath($DedicatedEvidencePath)}else{''});DedicatedEvidenceHash=$(if($external){$DedicatedEvidenceHash.ToLowerInvariant()}else{''});Owner=$Owner;Evidence=$Evidence;JournalHash=$state.JournalHash;ProducedUtc=(Get-WsmUtc);Mode='IsolatedPilot';ProductionVerified=$false}
        [void](Assert-WsmRollbackResultItemOutcomes $package.Plan $result);Write-WsmJson $Path $result;[pscustomobject]@{Path=[IO.Path]::GetFullPath($Path);SHA256=(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash;Result=$result}
    }
}
